WITH unpivoted AS (SELECT id, device_code, kpi, val FROM (SELECT id, device_code, pressure, temp_c FROM device_readings) src UNPIVOT (val FOR kpi IN (pressure AS PRESSURE_VAL, temp_c AS TEMP_C)) long_rows) SELECT CASE WHEN val >= 71 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_tier, APPROX_PERCENTILE(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, PERCENTILE_APPROX(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles_2, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count FROM unpivoted GROUP BY CUBE (CASE WHEN val >= 71 THEN 'PREMIUM' ELSE 'STANDARD' END);
